sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var custSysId = '{{step['5b0738177ac74c0598f9b476f65ad298'].record_id}}';
    var prodSysId = '{{step['01ce217ce6654a27b9b503ff9507e729'].record_id}}';
    var orderSysId = '', itemSysId = '';
    try {
        var now = new GlideDateTime();
        var delivery = new GlideDateTime(); delivery.addDaysLocalTime(14);
        var grO = new GlideRecord(P + 'cust_order');
        grO.initialize();
        grO.setValue('customer', custSysId);
        grO.setValue('order_date', now.getValue());
        grO.setValue('requested_delivery_date', delivery.getValue());
        grO.setValue('status', 'draft');
        grO.setValue('priority', 'medium');
        grO.setValue('order_type', 'standard');
        grO.setValue('active', true);
        grO.setValue('customer_reference', 'ATF-REF-CP06');
        orderSysId = grO.insert();
        assertEqual({ name: 'Order created', shouldbe: true, value: orderSysId.length > 0 });
        var grI = new GlideRecord(P + 'cust_ord_item');
        grI.initialize();
        grI.setValue('customer_order', orderSysId);
        grI.setValue('material_product', prodSysId);
        grI.setValue('quantity_ordered', 5);
        grI.setValue('unit_of_measure', 'EA');
        grI.setValue('active', true);
        itemSysId = grI.insert();
        assertEqual({ name: 'Item created', shouldbe: true, value: itemSysId.length > 0 });
        var grOrd = new GlideRecord(P + 'cust_order'); grOrd.get(orderSysId);
        assertEqual({ name: 'Order number displayed', shouldbe: true, value: (grOrd.getValue('number') || '').length > 0 });
        assertEqual({ name: 'Customer correct', shouldbe: custSysId, value: grOrd.getValue('customer') });
        assertEqual({ name: 'Order date displayed', shouldbe: true, value: grOrd.getValue('order_date') !== null });
        assertEqual({ name: 'Delivery date displayed', shouldbe: true, value: grOrd.getValue('requested_delivery_date') !== null });
        assertEqual({ name: 'Status displayed', shouldbe: true, value: (grOrd.getValue('status') || '').length > 0 });
        var grItems = new GlideRecord(P + 'cust_ord_item'); grItems.addQuery('customer_order', orderSysId); grItems.query();
        var ic = 0, tq = 0;
        while (grItems.next()) { ic++; tq += parseInt(grItems.getValue('quantity_ordered')) || 0; }
        assertEqual({ name: 'Items displayed', shouldbe: true, value: ic > 0 });
        assertEqual({ name: 'Total qty correct', shouldbe: 5, value: tq });
        assertEqual({ name: 'Customer ref correct', shouldbe: 'ATF-REF-CP06', value: grOrd.getValue('customer_reference') });
        var grU = new GlideRecord(P + 'cust_order'); grU.addQuery('sys_id', orderSysId); grU.addQuery('customer', 'ffffffffffffffffffffffffffffffff'); grU.query();
        assertEqual({ name: 'Unauthorized access blocked', shouldbe: false, value: grU.hasNext() });
        stepResult.setOutputMessage('Detail: Order=' + grOrd.getValue('number') + ' Items=' + ic + ' Qty=' + tq);
    } finally {
        if (itemSysId) { var d1 = new GlideRecord(P + 'cust_ord_item'); if (d1.get(itemSysId)) d1.deleteRecord(); }
        if (orderSysId) { var d2 = new GlideRecord(P + 'cust_order'); if (d2.get(orderSysId)) d2.deleteRecord(); }
    }
    return true;
})(outputs, steps, params, stepResult, assertEqual);
